{"path": "proverb.py", "content": "def proverb(*items, qualifier=None):
    """Return the proverb lines built from the given items."""
    if not items:
        return []
    lines = [
        f"For want of a {want} the {lost} was lost."
        for want, lost in zip(items, items[1:])
    ]
    first = f"{qualifier} {items[0]}" if qualifier else items[0]
    lines.append(f"And all for the want of a {first}.")
    return lines
